package games.enchanted.eg_particle_interactions.common.mixin.client.entity;
import games.enchanted.eg_particle_interactions.common.config.ConfigOptions; import games.enchanted.eg_particle_interactions.common.particle.ParticleSpawner; import net.minecraft.entity.Entity; import net.minecraft.entity.vehicle.AbstractMinecartEntity; import net.minecraft.util.math.Vec3d; import net.minecraft.world.World; import org.spongepowered.asm.mixin.Mixin; import org.spongepowered.asm.mixin.injection.At; import org.spongepowered.asm.mixin.injection.Inject; import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(AbstractMinecartEntity.class) public abstract class AbstractMinecartEntityMixin {
 @Inject(method="tick",at=@At("TAIL")) private void egpi$wheelSparks(CallbackInfo ci){Entity e=(Entity)(Object)this;World w=e.getWorld();Vec3d v=e.getVelocity();if(ConfigOptions.get().enabled&&ConfigOptions.get().entityEffects&&w.isClient&&v.x*v.x+v.z*v.z>.025&&w.random.nextInt(8)==0)ParticleSpawner.spark(w,e.getX()-v.x*.4,e.getY()+.08,e.getZ()-v.z*.4);}
}
